SELECT fa.financial_account_id AS accountId, fa.owner_type AS ownerType, fa.child_id AS childId, fa.bank_name AS bankName, fa.account_name AS accountName, fa.account_product_type AS accountProductType, fa.balance, fa.account_status AS accountStatus, fa.link_status AS linkStatus, fga.financial_goal_id AS financialGoalId FROM financial_account fa LEFT JOIN financial_goal_account fga ON fga.financial_account_id = fa.financial_account_id WHERE fa.financial_account_id IN
#{accountId}
FOR UPDATE
